if (typeof SPECIES_BY_ID !== 'undefined') {
    for (var [name, pokemon] of Object.entries(backup_data.poks)) {
        var id = name.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (SPECIES_BY_ID[5][id]) SPECIES_BY_ID[5][id].abilities = pokemon.abilities;
    }
}
if (typeof calc !== 'undefined') {
    for (var item of backup_data.extra_items) {
        if (!calc.ITEMS[5].includes(item)) calc.ITEMS[5].push(item);
    }
}

// Dynamic Dex accepts the same file through its local override uploader.
var overrides = backup_data.dex && backup_data.dex.overrides;
if (typeof module === 'object' && module.exports && backup_data.dex) {
    module.exports.BattleSearchIndex = backup_data.dex.searchIndex;
    module.exports.BattleSearchIndexOffset = backup_data.dex.searchIndexOffset;
    module.exports.BattleSearchCountIndex = backup_data.dex.searchIndexCount;
}
// Loaded with the custom data file; keep the hosted app's existing feature handlers.
if (typeof applyBlankDevConfig === 'function' && typeof devDataOverrides !== 'undefined') {
    var featureConfig = devDataOverrides.getStoredDevConfig() || getCurrentDevBlankConfig();
    if (localStorage.getItem('sacredGoldFeatures1') !== '1') {
        Object.assign(featureConfig, {showDex:true,showAI:true,noSwitch:false});
        localStorage.syncLua = '1';
        params.delete('noSwitch');
        params.delete('forceBlankConfig');
        var featureUrl = new URL(document.location.href);
        featureUrl.searchParams.delete('noSwitch');
        featureUrl.searchParams.delete('forceBlankConfig');
        history.replaceState({},'',featureUrl);
        localStorage.setItem('sacredGoldFeatures1','1');
        devDataOverrides.saveStoredDevConfig(featureConfig);
    }
    applyBlankDevConfig(featureConfig);

    if (!applySyncLuaVisibility.sacredGold) {
        var upstreamSyncVisibility = applySyncLuaVisibility;
        applySyncLuaVisibility = function () {
            upstreamSyncVisibility();
            if (typeof TITLE === 'string' && TITLE.startsWith('Sacred Gold Reforged')) {
                $('#sync-master').hide();
                $('#sync-lua').toggle(localStorage.syncLua === '1').text('Sync DeSmuME');
            }
        };
        applySyncLuaVisibility.sacredGold = true;
        var upstreamBaseGame = setBaseGame;
        setBaseGame = function (title) {
            upstreamBaseGame(title);
            applySyncLuaVisibility();
        };
    }

    if (!getDexFrameUrl.sacredGold) {
        var upstreamDexFrameUrl = getDexFrameUrl;
        getDexFrameUrl = function (path,options) {
            var url = new URL(upstreamDexFrameUrl(path,options));
            // Custom overrides are cached by Dynamic Dex; a game= key clears them.
            url.searchParams.delete('game');
            return url.toString();
        };
        getDexFrameUrl.sacredGold = true;
    }

    $(document).ready(function () {
        applySyncLuaVisibility();
        for (var frame of document.querySelectorAll('iframe.dex-window')) {
            var dexUrl = new URL(frame.src);
            if (dexUrl.searchParams.has('game')) {
                dexUrl.searchParams.delete('game');
                frame.dataset.dexFrameUrl = dexUrl.toString();
                frame.src = dexUrl.toString();
            }
        }
        if (!document.getElementById('sacred-gold-feature-note')) {
            var note = document.createElement('p');
            note.id = 'sacred-gold-feature-note';
            note.textContent = 'Dex setup: in the Dex tab, open More and upload this same SacredGold-Reforged.js file. AI and switch previews are experimental for Reforged.';
            note.style.cssText = 'font-size:0.85em;margin:8px 0;';
            document.querySelector('.app-header-shell').after(note);
        }
    });
}
